import { test } from "node:test";
import assert from "node:assert/strict";
import { createPushGate } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/courier-inv-g2-3/bot.mjs";

const base = { id: "u_8841", timeZone: "Asia/Tokyo", quietStart: "22:00", quietEnd: "07:00", dailyCap: 3 };
// Tokyo is UTC+9, no DST. Build instants from a Tokyo wall-clock time.
const tokyo = (s) => new Date(`${s}+09:00`);

test("allows a push in the day and returns null reason", () => {
  const g = createPushGate();
  assert.deepEqual(g.attempt(base, tokyo("2026-10-22T12:00:00")), { allowed: true, reason: null });
});

test("quiet hours wrap midnight, both sides", () => {
  const g = createPushGate();
  assert.equal(g.attempt(base, tokyo("2026-10-22T22:00:00")).reason, "quiet_hours");
  assert.equal(g.attempt(base, tokyo("2026-10-22T23:30:00")).reason, "quiet_hours");
  assert.equal(g.attempt(base, tokyo("2026-10-23T00:00:00")).reason, "quiet_hours");
  assert.equal(g.attempt(base, tokyo("2026-10-23T06:59:00")).reason, "quiet_hours");
  assert.equal(g.attempt(base, tokyo("2026-10-23T07:00:00")).allowed, true); // end is exclusive
});

test("quiet hours use the user's zone, not UTC", () => {
  const g = createPushGate();
  // 23:00 in Tokyo is 14:00 UTC; quiet in Tokyo, but daytime for a UTC server.
  assert.equal(g.attempt(base, new Date("2026-10-22T14:00:00Z")).reason, "quiet_hours");
  // 12:00 in Tokyo is 03:00 UTC; allowed in Tokyo even though it is night in UTC.
  assert.equal(g.attempt({ ...base, id: "u_day" }, new Date("2026-10-22T03:00:00Z")).allowed, true);
});

test("quiet window that does not cross midnight", () => {
  const g = createPushGate();
  const u = { ...base, quietStart: "13:00", quietEnd: "14:00" };
  assert.equal(g.attempt(u, tokyo("2026-10-22T13:30:00")).reason, "quiet_hours");
  assert.equal(g.attempt(u, tokyo("2026-10-22T14:00:00")).allowed, true);
});

test("equal start and end means no quiet period; absent fields mean none", () => {
  const g = createPushGate();
  assert.equal(g.attempt({ ...base, id: "a", quietStart: "09:00", quietEnd: "09:00" }, tokyo("2026-10-22T09:00:00")).allowed, true);
  assert.equal(g.attempt({ ...base, id: "b", quietStart: undefined, quietEnd: undefined }, tokyo("2026-10-22T23:00:00")).allowed, true);
});

test("daily cap counts the user's local calendar day, not a rolling 24h", () => {
  const g = createPushGate();
  const u = { ...base, id: "cap", dailyCap: 2 };
  assert.equal(g.attempt(u, tokyo("2026-10-22T10:00:00")).allowed, true);
  assert.equal(g.attempt(u, tokyo("2026-10-22T11:00:00")).allowed, true);
  assert.equal(g.attempt(u, tokyo("2026-10-22T20:00:00")).reason, "daily_cap_reached");
  // 25 hours after the first push, but a new local day: resets.
  assert.equal(g.attempt(u, tokyo("2026-10-23T08:00:00")).allowed, true);
});

test("local midnight starts a new day even though the 24h gap is shorter", () => {
  const g = createPushGate();
  const u = { ...base, id: "midnight", dailyCap: 1, quietStart: "02:00", quietEnd: "02:00" };
  assert.equal(g.attempt(u, tokyo("2026-10-22T23:50:00")).allowed, true);
  assert.equal(g.attempt(u, tokyo("2026-10-23T00:10:00")).allowed, true); // 20 min later, new day
});

test("a denied attempt does not count toward the cap", () => {
  const g = createPushGate();
  const u = { ...base, id: "denied", dailyCap: 1 };
  assert.equal(g.attempt(u, tokyo("2026-10-22T23:00:00")).reason, "quiet_hours");
  assert.equal(g.attempt(u, tokyo("2026-10-22T12:00:00")).allowed, true);
});

test("dailyCap 0 blocks every push with daily_cap_reached", () => {
  const g = createPushGate();
  assert.equal(g.attempt({ ...base, id: "zero", dailyCap: 0 }, tokyo("2026-10-22T12:00:00")).reason, "daily_cap_reached");
});

test("users are tracked independently and caps can differ per call", () => {
  const g = createPushGate();
  const a = { ...base, id: "a", dailyCap: 1 };
  const b = { ...base, id: "b", dailyCap: 1 };
  assert.equal(g.attempt(a, tokyo("2026-10-22T12:00:00")).allowed, true);
  assert.equal(g.attempt(a, tokyo("2026-10-22T13:00:00")).reason, "daily_cap_reached");
  assert.equal(g.attempt(b, tokyo("2026-10-22T13:00:00")).allowed, true);
  // Same user, cap raised on a later call: the new value applies.
  assert.equal(g.attempt({ ...a, dailyCap: 5 }, tokyo("2026-10-22T14:00:00")).allowed, true);
});

test("separate gates have separate history", () => {
  const u = { ...base, id: "iso", dailyCap: 1 };
  assert.equal(createPushGate().attempt(u, tokyo("2026-10-22T12:00:00")).allowed, true);
  assert.equal(createPushGate().attempt(u, tokyo("2026-10-22T12:01:00")).allowed, true);
});

test("the same user's local day follows the zone passed in the call", () => {
  const g = createPushGate();
  const ny = { id: "travel", timeZone: "America/New_York", quietStart: "22:00", quietEnd: "07:00", dailyCap: 1 };
  // 2026-10-22 12:00 New York (EDT, UTC-4) is 16:00Z.
  assert.equal(g.attempt(ny, new Date("2026-10-22T16:00:00Z")).allowed, true);
  // 2026-10-22 23:00 in Tokyo is quiet; but after moving to Tokyo the local date is 10-23 at 08:00 and cap is fresh.
  assert.equal(g.attempt({ ...base, id: "travel", dailyCap: 1 }, tokyo("2026-10-23T08:00:00")).allowed, true);
});

test("DST: New York spring-forward day still works", () => {
  const g = createPushGate();
  const ny = { id: "dst", timeZone: "America/New_York", quietStart: "22:00", quietEnd: "07:00", dailyCap: 5 };
  // 2026-03-08 is the US spring-forward day (02:00 -> 03:00 local).
  assert.equal(g.attempt(ny, new Date("2026-03-08T12:00:00Z")).allowed, true); // 08:00 EDT
  assert.equal(g.attempt(ny, new Date("2026-03-08T06:30:00Z")).reason, "quiet_hours"); // 01:30 EST, quiet
});

test("invalid settings return specific codes", () => {
  const g = createPushGate();
  const t = tokyo("2026-10-22T12:00:00");
  assert.equal(g.attempt({ ...base, id: "x1", timeZone: "Mars/Olympus" }, t).reason, "invalid_timezone");
  assert.equal(g.attempt({ ...base, id: "x2", timeZone: "" }, t).reason, "invalid_timezone");
  assert.equal(g.attempt({ ...base, id: "x3", quietStart: "25:00" }, t).reason, "invalid_quiet_hours");
  assert.equal(g.attempt({ ...base, id: "x4", quietEnd: "7:00" }, t).reason, "invalid_quiet_hours");
  assert.equal(g.attempt({ ...base, id: "x5", quietStart: null }, t).reason, "invalid_quiet_hours");
  assert.equal(g.attempt({ ...base, id: "x6", dailyCap: -1 }, t).reason, "invalid_daily_cap");
  assert.equal(g.attempt({ ...base, id: "x7", dailyCap: 1.5 }, t).reason, "invalid_daily_cap");
  assert.equal(g.attempt({ ...base, id: "x8", dailyCap: "3" }, t).reason, "invalid_daily_cap");
});

test("programmer errors throw", () => {
  const g = createPushGate();
  assert.throws(() => g.attempt(base, "2026-10-22"), TypeError);
  assert.throws(() => g.attempt(base, new Date("nope")), TypeError);
  assert.throws(() => g.attempt({ timeZone: "UTC" }, new Date()), TypeError);
});

test("returns a sync value, not a promise", () => {
  const r = createPushGate().attempt({ ...base, id: "sync" }, tokyo("2026-10-22T12:00:00"));
  assert.equal(typeof r.then, "undefined");
});
